(function(){"use strict";var burger=document.querySelector(".burger");var menu=document.getElementById("menu-principal");if(burger&&menu){burger.addEventListener("click",function(){var open=burger.getAttribute("aria-expanded")==="true";burger.setAttribute("aria-expanded",String(!open));burger.setAttribute("aria-label",open?"Ouvrir le menu":"Fermer le menu");menu.classList.toggle("is-open",!open);});document.addEventListener("keydown",function(e){if(e.key==="Escape"&&burger.getAttribute("aria-expanded")==="true"){burger.click();burger.focus();}});}var toTop=document.querySelector(".to-top");if(toTop){var update=function(){toTop.classList.toggle("is-visible",window.scrollY>300);};window.addEventListener("scroll",update,{passive:true});update();}var email=document.getElementById("email");if(email){var address=email.getAttribute("data-u")+"@"+email.getAttribute("data-d");email.href="mailto:"+address;email.textContent=address;}var reduce=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)");var items=document.querySelectorAll(".faq details");Array.prototype.forEach.call(items,function(d){var summary=d.querySelector("summary");if(!summary||!d.animate){return;}var anim=null;summary.addEventListener("click",function(e){if(reduce&&reduce.matches){return;}e.preventDefault();var closing=d.open&&!d.classList.contains("is-closing");var start=d.offsetHeight;if(anim){anim.cancel();}var end;if(closing){d.open=false;end=d.offsetHeight;d.open=true;d.classList.add("is-closing");}else{d.classList.remove("is-closing");d.open=true;end=d.offsetHeight;}d.classList.add("is-animating");anim=d.animate({height:[start+"px",end+"px"]},{duration:250,easing:"ease-in-out"});anim.onfinish=function(){anim=null;if(closing){d.open=false;d.classList.remove("is-closing");}d.classList.remove("is-animating");};});});var root=document.documentElement;var imgs=document.querySelectorAll("main img:not(.ico)");var started=[];root.classList.add("img-ok");var settle=function(img,cls){img.classList.remove("img-wait");img.classList.add(cls);};var reveal=function(img){if(img.getAttribute("fetchpriority")==="high"){settle(img,"img-in");return;}requestAnimationFrame(function(){requestAnimationFrame(function(){settle(img,"img-in");});});};var start=function(img){started.push(img);if(img.complete){if(img.naturalWidth>0){reveal(img);}else{settle(img,"img-vis");}return;}var wait=img.getAttribute("loading")==="lazy"&&setTimeout(function(){img.classList.add("img-wait");},120);img.addEventListener("load",function(){clearTimeout(wait);reveal(img);},{once:true});img.addEventListener("error",function(){clearTimeout(wait);settle(img,"img-vis");},{once:true});};if("IntersectionObserver"in window){var io=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){io.unobserve(e.target);start(e.target);}});});Array.prototype.forEach.call(imgs,function(img){if(img.getAttribute("fetchpriority")==="high"){start(img);}else{io.observe(img);}});}else{Array.prototype.forEach.call(imgs,start);}setTimeout(function(){started.forEach(function(img){var c=img.classList;if(!c.contains("img-in")&&!c.contains("img-vis")&&!c.contains("img-wait")){c.add("img-vis");}});},3000);if(window.console&&console.log){console.log("%cFLEXARION%c\n\n« Te revoilà, Sacha. Tu as encore oublié la vanne, n'est-ce pas ? »\n\n"+"Sous la surface, quelqu'un se souvient déjà de ta visite.\n"+"Indice : ce que tu fais en 2156 s'écrit en 2306. Les fontaines d'Aix gardent la mémoire du chemin.\n\n"+"%c// Below Zero, un jeu du studio Flexarion. https://flexarion-officiel.github.io/below-zero/","font:800 22px/1.4 'Exo 2',system-ui,sans-serif;letter-spacing:.3em;color:#19B9D4;background:#071421;padding:8px 14px;border-left:4px solid #19B9D4","font:14px/1.6 'Exo 2',system-ui,sans-serif;color:#B7DDE8","font:12px/1.6 monospace;color:#E8EDF0;opacity:.7");}})();
